/* The Grounded Readings Library, group abr2 (GWG BLD 798). Written by build-readings.py; edit the data, then build again. */
(window.GGReadingsData = window.GGReadingsData || {})["abr2"] = [{"id":"abr-quran-parents","title":"Lower unto Them the Wing of Submission","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["home","dying","gratitude"],"text":"Thy Lord hath decreed, that ye worship none save Him, and (that ye show) kindness to parents. If one of them or both of them attain old age with thee, say not \"Fie\" unto them nor repulse them, but speak unto them a gracious word.\nAnd lower unto them the wing of submission through mercy, and say: My Lord! Have mercy on them both as they did care for me when I was little.","note":"Kindness to parents, especially in their old age; for families caring for an elder.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 17:23-24, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-light-verse","title":"The Verse of Light","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["funeral","hope","evening"],"text":"Allah is the Light of the heavens and the earth. The similitude of His light is as a niche wherein is a lamp. The lamp is in a glass. The glass is as it were a shining star. (This lamp is) kindled from a blessed tree, an olive neither of the East nor of the West, whose oil would almost glow forth (of itself) though no fire touched it. Light upon light. Allah guideth unto His light whom He will. And Allah speaketh to mankind in allegories, for Allah is Knower of all things.","note":"Light upon light: one of the best loved verses, beloved of Sufis.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 24:35, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-love-mercy","title":"Love and Mercy Between You","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["wedding","nature"],"text":"And of His signs is this: He created you of dust, and behold you human beings, ranging widely!\nAnd of His signs is this: He created for you helpmeets from yourselves that ye might find rest in them, and He ordained between you love and mercy. Lo! herein indeed are portents for folk who reflect.\nAnd of His signs is the creation of the heavens and the earth, and the difference of your languages and colours. Lo! herein indeed are portents for men of knowledge.","note":"Read at Muslim weddings: He ordained between you love and mercy.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 30:20-22, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-luqman","title":"From the Counsel of Luqman","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["home","daily"],"text":"And verily We gave Luqman wisdom, saying: Give thanks unto Allah; and whosoever giveth thanks, he giveth thanks for (the good of) his soul. And whosoever refuseth, Lo! Allah is Absolute, Owner of Praise.\nAnd (remember) when Luqman said unto his son, when he was exhorting him: O my dear son! Ascribe no partners unto Allah. Lo! to ascribe partners (unto Him) is a tremendous wrong.\nO my dear son! Lo! though it be but the weight of a grain of mustard-seed, and though it be in a rock, or in the heavens, or in the earth, Allah will bring it forth. Lo! Allah is Subtile, Aware.\nO my dear son! Establish worship and enjoin kindness and forbid iniquity, and persevere whatever may befall thee. Lo! that is of the steadfast heart of things.\nTurn not thy cheek in scorn toward folk, nor walk with pertness in the land. Lo! Allah loveth not each braggart boaster.","note":"A wise father's counsel to his son, read for families and graduations.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 31:12-18, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-peace-word","title":"Peace, the Word of a Merciful Lord","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["funeral","hope"],"text":"Lo! those who merit paradise this day are happily employed,\nThey and their wives, in pleasant shade, on thrones reclining;\nTheirs the fruit (of their good deeds) and theirs (all) that they ask;\nThe word from a Merciful Lord (for them) is: Peace!","note":"From Ya Sin, the surah recited beside the dying and at funerals.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 36:55-58, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-despair-not","title":"Despair Not of the Mercy of Allah","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["forgiveness","hope"],"text":"Say: O My slaves who have been prodigal to their own hurt! Despair not of the mercy of Allah, Who forgiveth all sins. Lo! He is the Forgiving, the Merciful.","note":"A verse of mercy for anyone carrying regret.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 39:53, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-call-on-me","title":"Call upon Me","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["daily","comfort"],"text":"And your Lord hath said: Pray unto Me and I will hear your prayer. Lo! those who scorn My service, they will enter hell, disgraced.","note":"An invitation to pray.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 40:60, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-nations-tribes","title":"Nations and Tribes","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["peace","celebration"],"text":"O mankind! Lo! We have created you male and female, and have made you nations and tribes that ye may know one another. Lo! the noblest of you, in the sight of Allah, is the best in conduct. Lo! Allah is Knower, Aware.","note":"Made into nations and tribes that you may know one another.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 49:13, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-jugular","title":"Nearer than the Jugular Vein","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","dying"],"text":"We verily created man and We know what his soul whispereth to him, and We are nearer to him than his jugular vein.","note":"God is nearer to us than our own life vein.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 50:16, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-rahman","title":"From the Beneficent (Ar-Rahman)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["nature","gratitude"],"text":"The Beneficent\nHath made known the Qur'an.\nHe hath created man.\nHe hath taught him utterance.\nThe sun and the moon are made punctual.\nThe stars and the trees prostrate.\nAnd the sky He hath uplifted; and He hath set the measure,\nThat ye exceed not the measure,\nBut observe the measure strictly, nor fall short thereof.\nAnd the earth hath He appointed for (His) creatures,\nWherein are fruit and sheathed palm-trees,\nHusked grain and scented herb.\nWhich is it, of the favours of your Lord, that ye deny?","translit":"Ar-Rahman. 'Allamal Quran.","note":"Which is it of the favours of your Lord that ye deny? The surah of creation's gifts.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 55:1-13, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-rahman-face","title":"All That Is on Earth Will Pass Away","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["funeral","grief"],"text":"Everyone that is thereon will pass away;\nThere remaineth but the Countenance of thy Lord of Might and Glory.","note":"Two verses read at funerals: there remaineth the Countenance of thy Lord.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 55:26-27, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-names","title":"He Is Allah","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["daily","blessing"],"text":"He is Allah, than Whom there is no other God, the Knower of the Invisible and the Visible. He is the Beneficent, Merciful.\nHe is Allah, than Whom there is no other God, the Sovereign Lord, the Holy One, Peace, the Keeper of Faith, the Guardian, the Majestic, the Compeller, the Superb. Glorified be Allah from all that they ascribe as partner (unto Him).\nHe is Allah, the Creator, the Shaper out of naught, the Fashioner. His are the most beautiful names. All that is in the heavens and the earth glorifieth Him, and He is the Mighty, the Wise.","note":"The closing verses of the surah of the Gathering, naming the beautiful names.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 59:22-24, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-trust","title":"Whosoever Putteth His Trust in Allah","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","healing"],"text":"Then, when they have reached their term, take them back in kindness or part from them in kindness, and call to witness two just men among you, and keep your testimony upright for Allah. Whoso believeth in Allah and the Last Day is exhorted to act thus. And whosoever keepeth his duty to Allah, Allah will appoint a way out for him,\nAnd will provide for him from (a quarter) whence he hath no expectation. And whosoever putteth his trust in Allah, He will suffice him. Lo! Allah bringeth His command to pass. Allah hath set a measure for all things.","note":"For uncertain days: He will appoint a way out.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 65:2-3, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-sovereignty","title":"Blessed Is He","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["funeral","evening"],"text":"Blessed is He in Whose hand is the Sovereignty, and, He is Able to do all things.\nWho hath created life and death that He may try you which of you is best in conduct; and He is the Mighty, the Forgiving,","note":"The opening of Al-Mulk, recited each night and at gravesides.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 67:1-2, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-soul-at-peace","title":"O Soul at Peace","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["funeral","dying","comfort"],"text":"But ah! thou soul at peace!\nReturn unto thy Lord, content in His good pleasure!\nEnter thou among My bondmen!\nEnter thou My Garden!","translit":"Ya ayyatuhan nafsul mutma'innah.","note":"Said over the one who has died: return unto thy Lord, content in His good pleasure.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 89:27-30, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-duha","title":"The Morning Hours (Ad-Duha)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["morning","comfort","grief"],"text":"By the morning hours\nAnd by the night when it is stillest,\nThy Lord hath not forsaken thee nor doth He hate thee,\nAnd verily the latter portion will be better for thee than the former,\nAnd verily thy Lord will give unto thee so that thou wilt be content.\nDid He not find thee an orphan and protect (thee)?\nDid He not find thee wandering and direct (thee)?\nDid He not find thee destitute and enrich (thee)?\nTherefor the orphan oppress not,\nTherefor the beggar drive not away,\nTherefor of the bounty of thy Lord be thy discourse.","translit":"Wad duha. Wal layli idha saja.","note":"Revealed to comfort the Prophet in a season of silence: thy Lord hath not forsaken thee.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 93:1-11, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-solace","title":"The Solace (Ash-Sharh)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","healing","hope"],"text":"Have We not caused thy bosom to dilate,\nAnd eased thee of the burden\nWhich weighed down thy back;\nAnd exalted thy fame?\nBut lo! with hardship goeth ease,\nLo! with hardship goeth ease;\nSo when thou art relieved, still toil\nAnd strive to please thy Lord.","translit":"Alam nashrah laka sadrak.","note":"With hardship goeth ease: read in hard seasons.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 94:1-8, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-qadr","title":"The Night of Power (Al-Qadr)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["season","peace","evening"],"text":"Lo! We revealed it on the Night of Predestination.\nAh, what will convey unto thee what the Night of Power is!\nThe Night of Power is better than a thousand months.\nThe angels and the Spirit descend therein, by the permission of their Lord, with all decrees.\n(The night is) Peace until the rising of the dawn.","note":"Read on the holy nights of Ramadan: peace until the rising of the dawn.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 97:1-5, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-asr","title":"The Declining Day (Al-Asr)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["daily","funeral"],"text":"By the declining day,\nLo! man is a state of loss,\nSave those who believe and do good works, and exhort one another to truth and exhort one another to endurance.","translit":"Wal 'asr. Innal insana lafi khusr.","note":"A short surah on time, faith, good works, truth, and patience.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 103:1-3, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-ikhlas","title":"The Unity (Al-Ikhlas)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["daily","funeral","evening"],"text":"Say: He is Allah, the One!\nAllah, the eternally Besought of all!\nHe begetteth not nor was begotten.\nAnd there is none comparable unto Him.","translit":"Qul huwallahu ahad. Allahus samad.","note":"A short surah of God's oneness, recited often and at funerals.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 112:1-4, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-falaq","title":"The Daybreak (Al-Falaq)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["evening","comfort","healing"],"text":"Say: I seek refuge in the Lord of the Daybreak\nFrom the evil of that which He created;\nFrom the evil of the darkness when it is intense,\nAnd from the evil of malignant witchcraft,\nAnd from the evil of the envier when he envieth.","translit":"Qul a'udhu birabbil falaq.","note":"Recited for protection, before sleep, and over the sick.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 113:1-5, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-nas","title":"Mankind (An-Nas)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["evening","comfort","healing"],"text":"Say: I seek refuge in the Lord of mankind,\nThe King of mankind,\nThe God of mankind,\nFrom the evil of the sneaking whisperer,\nWho whispereth in the hearts of mankind,\nOf the jinn and of mankind.","translit":"Qul a'udhu birabbin nas.","note":"The last surah, recited with the two before it for protection and peace.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 114:1-6, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-servants-beneficent","title":"The Servants of the Beneficent","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["peace","daily"],"text":"The (faithful) slaves of the Beneficent are they who walk upon the earth modestly, and when the foolish ones address them answer: Peace;","note":"They walk upon the earth modestly, and answer with peace.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 25:63, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-repel-good","title":"Repel the Evil Deed with One Better","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["forgiveness","peace"],"text":"The good deed and the evil deed are not alike. Repel the evil deed with one which is better, then lo! he, between whom and thee there was enmity (will become) as though he was a bosom friend.","note":"Answer harm with goodness, and an enemy may become a warm friend.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 41:34, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-leaf-falls","title":"Not a Leaf Falleth","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["nature","comfort"],"text":"And with Him are the keys of the Invisible. None but He knoweth them. And He knoweth what is in the land and the sea. Not a leaf falleth but He knoweth it, not a grain amid the darkness of the earth, naught of wet or dry but (it is noted) in a clear record.","note":"Nothing in creation is beyond His knowing, not even a falling leaf.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 6:59, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-mary-jesus","title":"Peace on Me the Day I Was Born","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["birth","funeral","peace"],"text":"He spake: Lo! I am the slave of Allah. He hath given me the Scripture and hath appointed me a Prophet,\nAnd hath made me blessed wheresoever I may be, and hath enjoined upon me prayer and almsgiving so long as I remain alive,\nAnd (hath made me) dutiful toward her who bore me, and hath not made me arrogant, unblest.\nPeace on me the day I was born, and the day I die, and the day I shall be raised alive!","note":"Jesus speaks from the cradle in the surah of Mary; loved by Muslims and Christians alike.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 19:30-33, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-good-tree","title":"A Goodly Word as a Goodly Tree","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["funeral","nature","celebration"],"text":"Seest thou not how Allah coineth a similitude: A goodly saying, as a goodly tree, its root set firm, its branches reaching into heaven,\nGiving its fruit at every season by permission of its Lord? Allah coineth the similitudes for mankind in order that they may reflect.","note":"A good word is like a good tree, its roots set firm and its branches in the sky: for a eulogy.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 14:24-25, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-patience-prayer","title":"Seek Help in Patience and Prayer","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","grief"],"text":"Seek help in patience and prayer; and truly it is hard save for the humble-minded,\nWho know that they will have to meet their Lord, and that unto Him they are returning.","note":"For those who will meet their Lord and unto Him are returning.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 2:45-46, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-seven-seas","title":"If All the Trees Were Pens","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["gratitude","nature"],"text":"And if all the trees in the earth were pens, and the sea, with seven more seas to help it, (were ink), the words of Allah could not be exhausted. Lo! Allah is Mighty, Wise.","note":"The words of Allah could never be spent.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 31:27, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-moses-prayer","title":"My Lord, Relieve My Mind","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","healing","daily"],"text":"(Moses) said: My Lord! relieve my mind\nAnd ease my task for me;\nAnd loose a knot from my tongue,\nThat they may understand my saying.","translit":"Rabbish rahli sadri, wa yassir li amri.","note":"The prayer of Moses before a hard task, said before speaking or exams.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 20:25-28, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-job-prayer","title":"The Prayer of Job","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["healing","comfort"],"text":"And Job, when he cried unto his Lord, (saying): Lo! adversity afflicteth me, and Thou art Most Merciful of all who show mercy.\nThen We heard his prayer and removed that adversity from which he suffered, and We gave him his household (that he had lost) and the like thereof along with them, a mercy from Our store, and a remembrance for the worshippers;","note":"Said for the sick: Thou art the Most Merciful of all who show mercy.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 21:83-84, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-jonah-prayer","title":"The Prayer of Jonah","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","forgiveness"],"text":"And (mention) Dhu'n-Nun, when he went off in anger and deemed that We had no power over him, but he cried out in the darkness, saying: There is no God save Thee. Be Thou Glorified! Lo! I have been a wrong-doer.\nThen we heard his prayer and saved him from the anguish. Thus we save believers.","translit":"La ilaha illa anta subhanaka inni kuntu minaz zalimin.","note":"Said in distress, as Jonah prayed from the darkness.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 21:87-88, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-cave-prayer","title":"Give Us Mercy from Thy Presence","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["comfort","hope"],"text":"When the young men fled for refuge to the Cave and said: Our Lord! Give us mercy from Thy presence, and shape for us right conduct in our plight.","note":"The prayer of the young people who sheltered in the cave.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 18:10, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-first-last","title":"He Is the First and the Last","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["funeral","nature"],"text":"All that is in the heavens and the earth glorifieth Allah; and He is the Mighty, the Wise.\nHis is the Sovereignty of the heavens and the earth; He quickeneth and He giveth death; and He is Able to do all things.\nHe is the First and the Last, and the Outward and the Inward; and He is Knower of all things.\nHe it is Who created the heavens and the earth in six Days; then He mounted the Throne. He knoweth all that entereth the earth and all that emergeth therefrom and all that cometh down from the sky and all that ascendeth therein; and He is with you wheresoever ye may be. And Allah is Seer of what ye do.","note":"He is with you wheresoever ye may be.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 57:1-4, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-grain","title":"A Grain That Groweth Seven Ears","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["gratitude","celebration"],"text":"The likeness of those who spend their wealth in Allah's way is as the likeness of a grain which groweth seven ears, in every ear a hundred grains. Allah giveth increase manifold to whom He will. Allah is All-Embracing, All-Knowing.","note":"A parable of generous giving that multiplies.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 2:261, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-for-love-of-him","title":"For the Love of Him","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["daily","gratitude"],"text":"And feed with food the needy wretch, the orphan and the prisoner, for love of Him,\n(Saying): We feed you, for the sake of Allah only. We wish for no reward nor thanks from you;","note":"Feeding the needy, the orphan, and the prisoner for the love of God, wishing no reward.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 76:8-9, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-calamity","title":"By the Leave of Allah","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["grief","comfort"],"text":"No calamity befalleth save by Allah's leave. And whosoever believeth in Allah, He guideth his heart. And Allah is Knower of all things.","note":"For one who has met with loss: He guideth his heart.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 64:11, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-all-praise","title":"All Things Glorify Him","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["nature","gratitude"],"text":"The seven heavens and the earth and all that is therein praise Him, and there is not a thing but hymneth His praise; but ye understand not their praise. Lo! He is ever Clement, Forgiving.","note":"The seven heavens and the earth and all within them sing praise.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 17:44, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-kawthar","title":"Abundance (Al-Kawthar)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["gratitude","birth"],"text":"Lo! We have given thee Abundance;\nSo pray unto thy Lord, and sacrifice.\nLo! it is thy insulter (and not thou) who is without posterity.","note":"The shortest surah, a gift of abundance.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 108:1-3, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-succour","title":"Succour (An-Nasr)","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["celebration","forgiveness"],"text":"When Allah's succour and the triumph cometh\nAnd thou seest mankind entering the religion of Allah in troops,\nThen hymn the praises of thy Lord, and seek forgiveness of Him. Lo! He is ever ready to show mercy.","note":"When help and victory come: give praise and seek forgiveness.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 110:1-3, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-steadfast-hearts","title":"Cause Not Our Hearts to Stray","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["daily","hope"],"text":"Our Lord! Cause not our hearts to stray after Thou hast guided us, and bestow upon us mercy from Thy Presence. Lo! Thou, only Thou, art the Bestower.","translit":"Rabbana la tuzigh qulubana.","note":"A short prayer for a steady heart.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 3:8, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-adam-prayer","title":"The Prayer of Adam and Eve","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["forgiveness"],"text":"They said: Our Lord! We have wronged ourselves. If thou forgive us not and have not mercy on us, surely we are of the lost!","translit":"Rabbana zalamna anfusana.","note":"The first prayer for forgiveness in the Quran.","voice":"brian","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 7:23, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-quran-forgive-mercy","title":"Forgive and Have Mercy","by":"The Quran","tr":"Marmaduke Pickthall","year":1930,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"scripture","occasion":["forgiveness","funeral","dying"],"text":"And (O Muhammad) say: My Lord! Forgive and have mercy, for Thou art best of all who show mercy.","note":"The closing verse of the surah of the Believers, said for the living and the dead.","voice":"jenny","source":{"name":"The Meaning of the Glorious Koran, tr. Pickthall (1930), Surah 23:118, Project Gutenberg #16955","url":"https://www.gutenberg.org/ebooks/16955"},"rights":"pd","pd":"The Meaning of the Glorious Koran, published 1930; public domain in the United States since January 1, 2026"},{"id":"abr-hadith-kindness","title":"Sayings of the Prophet on Mercy and Kindness","by":"The Prophet Muhammad, from the Traditions","tr":"John Wortabet","year":1907,"trad":["muslim"],"denom":["sunni","shia","sufi"],"type":"reflection","occasion":["daily","forgiveness","peace"],"text":"He who forgiveth others, God forgiveth him.\nBe merciful, and you will have mercy; forgive and you will be forgiven.\nBe friendly to him who would be unfriendly to you, give him who will not give you, and forbear with him who would do you harm.\nNext to faith in God, the chief duty of man is to treat his fellow men with gentleness and courtesy.\nGod's creatures are the objects of His care, and He loveth best that man who is most helpful to them.\nBe ever truthful, for truthfulness leads to righteousness, and righteousness leads to heaven.","note":"Traditions of the Prophet on forgiveness, gentleness, care for creation, and truth.","voice":"brian","source":{"name":"John Wortabet, Arabian Wisdom (Wisdom of the East, 1907; 1916 printing), Project Gutenberg #33109","url":"https://www.gutenberg.org/ebooks/33109"},"rights":"pd","pd":"first published 1907 (John Murray, London); Wortabet died 1908"},{"id":"abr-rumi-bier","title":"When My Bier Moveth","by":"Jalal al-Din Rumi","tr":"R. A. Nicholson and E. H. Whinfield, selected by F. Hadland Davis","year":1907,"trad":["muslim","sbnr"],"denom":["sufi"],"type":"poem","occasion":["funeral","dying","grief"],"text":"When my bier moveth on the day of Death,\nThink not my heart is in this world.\nDo not weep in the devil's snare: that is woe.\nWhen thou seest my hearse, cry not \"Parted, parted!\"\nUnion and meeting are mine in that hour.\nIf thou commit me to the grave, say not \"Farewell, farewell!\"\nFor the grave is a curtain hiding the communion of Paradise,\nAfter beholding descent, consider resurrection;\nWhy should setting be injurious to the sun and moon?\nTo thee it seems a setting, but 'tis a rising;\nTho' the vault seems a prison, 'tis the release of the soul.\nShut thy mouth on this side and open it beyond,\nFor in placeless air will be thy triumphal song.","note":"Rumi on death as a rising, read at funerals of many faiths.","voice":"jenny","source":{"name":"F. Hadland Davis, The Persian Mystics: Jalalu'd-din Rumi (Wisdom of the East, 1907), Project Gutenberg #45159","url":"https://www.gutenberg.org/ebooks/45159"},"rights":"pd","pd":"published 1907 (John Murray, London); public domain in the United States"},{"id":"abr-rumi-dust-spirit","title":"Thou Wert Dust and Art Spirit","by":"Jalal al-Din Rumi","tr":"R. A. Nicholson and E. H. Whinfield, selected by F. Hadland Davis","year":1907,"trad":["muslim"],"denom":["sufi"],"type":"poem","occasion":["funeral","birth","hope"],"text":"On every side is clamour and tumult, in every street are candles and torches,\nFor to-night the teeming world gives birth to the World Everlasting.\nThou wert dust and art spirit, thou wert ignorant and art wise.\nHe who has led thee thus far will lead thee further also.\nHow pleasant are the pains He makes thee suffer while He gently draws thee to Himself!","note":"He who has led thee thus far will lead thee further also.","voice":"brian","source":{"name":"F. Hadland Davis, The Persian Mystics: Jalalu'd-din Rumi (Wisdom of the East, 1907), Project Gutenberg #45159","url":"https://www.gutenberg.org/ebooks/45159"},"rights":"pd","pd":"published 1907 (John Murray, London); public domain in the United States"},{"id":"abr-rumi-all-religions","title":"All Religions Are One","by":"Jalal al-Din Rumi","tr":"R. A. Nicholson and E. H. Whinfield, selected by F. Hadland Davis","year":1907,"trad":["muslim","all"],"denom":["sufi"],"type":"poem","occasion":["peace","celebration"],"text":"In the adorations and benedictions of righteous men\nThe praises of all the prophets are kneaded together.\nAll their praises are mingled into one stream,\nAll the vessels are emptied into one ewer.\nBecause He that is praised is, in fact, only One.\nIn this respect all religions are only one religion.\nBecause all praises are directed towards God's Light,\nThese various forms and figures are borrowed from it.","note":"Rumi on the one Light behind every form of praise; a fine interfaith reading.","voice":"jenny","source":{"name":"F. Hadland Davis, The Persian Mystics: Jalalu'd-din Rumi (Wisdom of the East, 1907), Project Gutenberg #45159","url":"https://www.gutenberg.org/ebooks/45159"},"rights":"pd","pd":"published 1907 (John Murray, London); public domain in the United States"},{"id":"abr-rumi-silence-of-love","title":"The Silence of Love","by":"Jalal al-Din Rumi","tr":"R. A. Nicholson and E. H. Whinfield, selected by F. Hadland Davis","year":1907,"trad":["muslim"],"denom":["sufi"],"type":"poem","occasion":["wedding","celebration"],"text":"Love is the astrolabe of God's mysteries.\nA lover may hanker after this love or that love,\nBut at the last he is drawn to the KING of Love.\nHowever much we describe and explain Love,\nWhen we fall in love we are ashamed of our words.\nExplanation by the tongue makes most things clear,\nBut Love unexplained is better.","note":"For a wedding: love is beyond our words.","voice":"brian","source":{"name":"F. Hadland Davis, The Persian Mystics: Jalalu'd-din Rumi (Wisdom of the East, 1907), Project Gutenberg #45159","url":"https://www.gutenberg.org/ebooks/45159"},"rights":"pd","pd":"published 1907 (John Murray, London); public domain in the United States"},{"id":"abr-rumi-rose-thorn","title":"Sorrow Turned to Joy","by":"Jalal al-Din Rumi","tr":"R. A. Nicholson and E. H. Whinfield, selected by F. Hadland Davis","year":1907,"trad":["muslim"],"denom":["sufi"],"type":"poem","occasion":["grief","hope","season"],"text":"He who extracts the rose from the thorn\nCan also turn this winter into spring.\nHe who exalts the heads of the cypresses\nIs able also out of sadness to bring joy.","note":"Four lines of hope for a winter season.","voice":"jenny","source":{"name":"F. Hadland Davis, The Persian Mystics: Jalalu'd-din Rumi (Wisdom of the East, 1907), Project Gutenberg #45159","url":"https://www.gutenberg.org/ebooks/45159"},"rights":"pd","pd":"published 1907 (John Murray, London); public domain in the United States"},{"id":"abr-rumi-love-light","title":"Love Casts Its Own Light","by":"Jalal al-Din Rumi","tr":"R. A. Nicholson and E. H. Whinfield, selected by F. Hadland Davis","year":1907,"trad":["muslim"],"denom":["sufi"],"type":"poem","occasion":["daily","evening"],"text":"When love of God kindles a flame in the inward man,\nHe burns, and is freed from effects.\nHe has no need of signs to assure him of Love,\nFor Love casts its own Light up to heaven.","note":"A short poem on the light of love.","voice":"brian","source":{"name":"F. Hadland Davis, The Persian Mystics: Jalalu'd-din Rumi (Wisdom of the East, 1907), Project Gutenberg #45159","url":"https://www.gutenberg.org/ebooks/45159"},"rights":"pd","pd":"published 1907 (John Murray, London); public domain in the United States"},{"id":"abr-rumi-prayer","title":"A Prayer from Rumi","by":"Jalal al-Din Rumi","tr":"R. A. Nicholson and E. H. Whinfield, selected by F. Hadland Davis","year":1907,"trad":["muslim"],"denom":["sufi"],"type":"poem","occasion":["daily","home","blessing"],"text":"Pray in this wise and allay your difficulties:\n'Give us good in the house of our present world,\nAnd give us good in the house of our next world.\nMake our path pleasant as a garden,\nAnd be Thou, O Holy One, our goal!'","note":"Give us good in this world and the next; a prayer for the path.","voice":"jenny","source":{"name":"F. Hadland Davis, The Persian Mystics: Jalalu'd-din Rumi (Wisdom of the East, 1907), Project Gutenberg #45159","url":"https://www.gutenberg.org/ebooks/45159"},"rights":"pd","pd":"published 1907 (John Murray, London); public domain in the United States"},{"id":"abr-rumi-divine-friend","title":"The Divine Friend","by":"Jalal al-Din Rumi","tr":"R. A. Nicholson and E. H. Whinfield, selected by F. Hadland Davis","year":1907,"trad":["muslim"],"denom":["sufi"],"type":"poem","occasion":["dying","comfort"],"text":"Look on me, for thou art my companion in the grave\nOn the night when thou shalt pass from shop and dwelling.\nThou shalt hear my hail in the hollow of the tomb: it shall become known to thee\nThat thou wast never concealed from mine eye.\nI am as reason and intellect within thy bosom\nAt the time of joy and gladness, at the time of sorrow and distress.","note":"The Friend speaks: thou wast never concealed from mine eye.","voice":"brian","source":{"name":"F. Hadland Davis, The Persian Mystics: Jalalu'd-din Rumi (Wisdom of the East, 1907), Project Gutenberg #45159","url":"https://www.gutenberg.org/ebooks/45159"},"rights":"pd","pd":"published 1907 (John Murray, London); public domain in the United States"},{"id":"abr-rumi-sorrow-quenched","title":"Do Thou Abide","by":"Jalal al-Din Rumi","tr":"R. A. Nicholson and E. H. Whinfield, selected by F. Hadland Davis","year":1907,"trad":["muslim"],"denom":["sufi"],"type":"poem","occasion":["grief","comfort"],"text":"Through grief my days are as labour and sorrow,\nMy days move on, hand in hand with anguish.\nYet, though my days vanish thus, 'tis no matter,\nDo Thou abide, O Incomparable Pure One.","note":"Four lines for a grieving heart.","voice":"jenny","source":{"name":"F. Hadland Davis, The Persian Mystics: Jalalu'd-din Rumi (Wisdom of the East, 1907), Project Gutenberg #45159","url":"https://www.gutenberg.org/ebooks/45159"},"rights":"pd","pd":"published 1907 (John Murray, London); public domain in the United States"},{"id":"abr-rabia-for-thy-sake","title":"For Thy Sake Only","by":"Rabia al-Adawiyya of Basra","tr":"Claud Field","year":1910,"trad":["muslim"],"denom":["sufi"],"type":"prayer","occasion":["daily","peace"],"text":"\"My God, if it is from fear of hell that I serve Thee, condemn me to burn in hell; and if it is for the hope of Paradise, forbid me entrance there; but if it is for Thy sake only, deny me not the sight of Thy face.\"","note":"Rabia's most famous prayer: love of God for God's own sake.","voice":"brian","source":{"name":"Claud Field, Mystics and Saints of Islam (1910), \"Rabia, the Woman Sufi,\" Project Gutenberg #24314","url":"https://www.gutenberg.org/ebooks/24314"},"rights":"pd","pd":"published 1910 (Francis Griffiths, London); Field died 1941; public domain in the United States"},{"id":"abr-rabia-enter-thyself","title":"Enter Rather into Thyself","by":"Rabia al-Adawiyya of Basra","tr":"Claud Field","year":1910,"trad":["muslim"],"denom":["sufi"],"type":"story","occasion":["daily","nature","peace"],"text":"Once when Rabia had immured herself for a long while in her house without coming forth, her servant said to her, \"Lady, come forth out of this house and contemplate the works of the Most High.\" \"Nay,\" said Rabia, \"enter rather into thyself and contemplate His work in thyself.\"","note":"A saint's answer when called outside to see creation.","voice":"jenny","source":{"name":"Claud Field, Mystics and Saints of Islam (1910), \"Rabia, the Woman Sufi,\" Project Gutenberg #24314","url":"https://www.gutenberg.org/ebooks/24314"},"rights":"pd","pd":"published 1910 (Francis Griffiths, London); Field died 1941; public domain in the United States"},{"id":"abr-rabia-alone-with-thee","title":"Alone with Thee","by":"Rabia al-Adawiyya of Basra","tr":"Claud Field","year":1910,"trad":["muslim"],"denom":["sufi"],"type":"story","occasion":["evening","peace"],"text":"Often in the silence of the night she would go on the roof of her house and say, 'The lover is now with his beloved, but I rejoice in being alone with Thee.'","note":"Rabia at prayer on her rooftop at night.","voice":"brian","source":{"name":"Claud Field, Mystics and Saints of Islam (1910), \"Rabia, the Woman Sufi,\" Project Gutenberg #24314","url":"https://www.gutenberg.org/ebooks/24314"},"rights":"pd","pd":"published 1910 (Francis Griffiths, London); Field died 1941; public domain in the United States"},{"id":"abr-rabia-sincerity","title":"What Sincerity Is","by":"Rabia al-Adawiyya of Basra","tr":"Claud Field","year":1910,"trad":["muslim"],"denom":["sufi"],"type":"story","occasion":["grief","comfort"],"text":"On one occasion when Malik Dinar, Hasan Basri and Shaqiq were with her, the conversation turned on sincerity of heart towards God. Hasan Basri said, \"He has not sincere love to God who does not bear with constancy the afflictions which the Lord sends him.\" \"That remark savours of self-conceit,\" said Rabia. Shaqiq observed, \"He is not sincere who does not render thanks for afflictions.\" \"There is a higher degree of sincerity than that,\" said Rabia. Malik Dinar suggested, \"He is not sincere who does not find delight in the afflictions which the Lord sends.\" \"That is not the purest sincerity,\" she remarked. Then they asked her to define sincerity. She said, \"He is not sincere who does not forget the pain of affliction through his absorption in God.\"","note":"Friends ask Rabia how a sincere heart bears sorrow.","voice":"jenny","source":{"name":"Claud Field, Mystics and Saints of Islam (1910), \"Rabia, the Woman Sufi,\" Project Gutenberg #24314","url":"https://www.gutenberg.org/ebooks/24314"},"rights":"pd","pd":"published 1910 (Francis Griffiths, London); Field died 1941; public domain in the United States"},{"id":"abr-saadi-sons-of-adam","title":"The Sons of Adam Are Members One of Another","by":"Saadi of Shiraz","tr":"James Ross","year":1823,"trad":["muslim","all"],"denom":["sufi"],"type":"reflection","occasion":["peace","comfort","daily"],"text":"The sons of Adam are members one of another, for in their creation they have a common origin. If the vicissitudes of fortune involve one member in pain, all the other members will feel a sympathy. Thou, who art indifferent to other men's affliction, if they call thee a man art unworthy of the name.","note":"Saadi's famous lines on one human family, now woven over the entrance of the United Nations.","voice":"brian","source":{"name":"Saadi, The Gulistan, tr. James Ross (1823), in Persian Literature, vol. 2 (1900), Project Gutenberg #13060","url":"https://www.gutenberg.org/ebooks/13060"},"rights":"pd","pd":"Ross translation published 1823; this edition 1900"},{"id":"abr-jami-sea-of-being","title":"The Sea of Being","by":"Jami","tr":"E. H. Whinfield","year":1908,"trad":["muslim"],"denom":["sufi"],"type":"poem","occasion":["nature","peace"],"text":"Being's a sea in constant billows rolled,\n'Tis but these billows that we men behold;\nSped from within, they rest upon the sea,\nAnd like a veil its actual form enfold.\nBeing's the essence of the Lord of all,\nAll things exist in Him and He in all;\nThis is the meaning of the Gnostic phrase,\n\"All things are comprehended in the All.\"","note":"Jami on all things resting in the One, like waves on the sea.","voice":"jenny","source":{"name":"F. Hadland Davis, The Persian Mystics: Jami (Wisdom of the East, 1908), Project Gutenberg #45158","url":"https://www.gutenberg.org/ebooks/45158"},"rights":"pd","pd":"published 1908 (John Murray, London); public domain in the United States"},{"id":"abr-jami-friendship","title":"Friendship","by":"Jami","tr":"F. Hadland Davis (selection)","year":1908,"trad":["muslim"],"denom":["sufi"],"type":"poem","occasion":["celebration","forgiveness"],"text":"He is a friend, who although meeting with enmity\nFrom his friend, only becomes more attached to him.\nIf he strikes him with a thousand stones of violence,\nThe edifice of his love will only be made more firm by them.","note":"Four lines on a friendship that only grows firmer.","voice":"brian","source":{"name":"F. Hadland Davis, The Persian Mystics: Jami (Wisdom of the East, 1908), Project Gutenberg #45158","url":"https://www.gutenberg.org/ebooks/45158"},"rights":"pd","pd":"published 1908 (John Murray, London); public domain in the United States"},{"id":"abr-gb-muslim-bedside","title":"At a Muslim Bedside","by":"Grow With Grounded","year":2026,"trad":["muslim"],"type":"blessing","occasion":["dying","comfort"],"text":"We are here with you.\nThe family is near, the Quran is near, and God is nearer still.\nMay this room be filled with peace,\nmay every breath be gentle,\nand may the words of mercy you love be the last words you hear.","note":"A Grounded word for a helper sitting with a Muslim family; the family leads the prayers.","voice":"jenny","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded","denom":[]},{"id":"abr-gb-janazah-family","title":"For the Family After the Janazah","by":"Grow With Grounded","year":2026,"trad":["muslim"],"type":"blessing","occasion":["grief","funeral"],"text":"To God we belong, and to God we return.\nWe hold you in your grief and we honor the life you loved.\nMay your home be full of visitors, food, and kind remembrance.\nMay the mercy of the Most Merciful surround the one you miss,\nand may patience and peace settle on your hearts.","note":"A Grounded word for visitors in the days of mourning after the funeral prayer.","voice":"brian","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded","denom":[]},{"id":"abr-gb-eid","title":"An Eid Blessing","by":"Grow With Grounded","year":2026,"trad":["muslim"],"type":"blessing","occasion":["celebration","season","gratitude"],"text":"Eid Mubarak.\nMay your table be full and your home be bright.\nMay the fasting and giving of this season stay with you as kindness all year,\nand may every person you love be close today.","translit":"Eid Mubarak.","note":"A Grounded word of greeting for Eid with a Muslim friend or family.","voice":"jenny","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded","denom":[]},{"id":"abr-bahai-little-babe","title":"For a Newborn Child","by":"'Abdu'l-Baha","year":1909,"trad":["bahai"],"type":"prayer","occasion":["birth","blessing"],"text":"O God! Rear this little babe in the bosom of Thy love and give it milk from the breast of Providence. Cultivate this fresh plant in the rose-garden of Thy love and nurture it by showers from the clouds of Providence. Make it a child of the Kingdom and lead it to the divine world. Thou art powerful and kind! Thou art the Giver, the Bestower, whose blessings precede all else!","note":"A prayer for a baby, given by Abdu'l-Baha to parents naming their child.","voice":"jenny","source":{"name":"Tablets of Abdul-Baha Abbas, vol. 1 (Bahai Publishing Society, Chicago, 1909), Project Gutenberg #19312","url":"https://www.gutenberg.org/ebooks/19312"},"rights":"pd","pd":"published 1909 in Chicago; public domain in the United States. The Project Gutenberg file also carries the Baha'i International Community notice","denom":[]},{"id":"abr-bahai-young-child","title":"A Prayer of a Young Child","by":"'Abdu'l-Baha","year":1909,"trad":["bahai"],"type":"prayer","occasion":["daily","healing","comfort"],"text":"O loving God! I am a young child, a suppliant, a captive. Be Thou my refuge, my support, my protector. I am in distress: give me the means of tranquillity. I am needy: bestow upon me the treasure of the Kingdom. I am dead: give me the Spirit of Life. I am weak: favor me with power and strength, so that I may be a maid-servant in Thy Threshold, with perfect purity and sanctity; sacrifice myself unto Thee, be quit of myself and seek Thee, walk in the path of Thy good pleasure, speak Thy secret and witness the signs of Thy Oneness wherever I look. O God! Make me ablaze, like unto the fire of Thy love, and make me free from attachment to this mortal world, until I find the peace of soul and the rest of conscience.\nThou art the Powerful, the Mighty! Thou art the Hearer, the Seer!","note":"A child's prayer for refuge, strength, and peace of soul.","voice":"brian","source":{"name":"Tablets of Abdul-Baha Abbas, vol. 1 (Bahai Publishing Society, Chicago, 1909), Project Gutenberg #19312","url":"https://www.gutenberg.org/ebooks/19312"},"rights":"pd","pd":"published 1909 in Chicago; public domain in the United States. The Project Gutenberg file also carries the Baha'i International Community notice","denom":[]},{"id":"abr-bahai-forgiving-lord","title":"For Those Who Have Passed On","by":"'Abdu'l-Baha","year":1909,"trad":["bahai"],"type":"prayer","occasion":["funeral","forgiveness","grief"],"text":"O Thou Forgiving Lord!\nAlthough certain souls finished the days of life in ignorance, were estranged and selfish, yet the ocean of Thy forgiveness is, verily, able to redeem and make free the sinners by one of its waves. Thou redeemest whomsoever Thou willest and deprivest whomsoever Thou willest not! Shouldst Thou treat justly, we all are sinners and deserve to be deprived; and shouldst Thou observe mercy, every sinner shall be made pure and every stranger shall become a friend. Therefore, forgive and pardon and grant Thy mercy unto all. Thou art the Forgiver, the Light-giver and the Compassionate!","note":"A prayer that the ocean of mercy will reach every soul that has died.","voice":"jenny","source":{"name":"Tablets of Abdul-Baha Abbas, vol. 1 (Bahai Publishing Society, Chicago, 1909), Project Gutenberg #19312","url":"https://www.gutenberg.org/ebooks/19312"},"rights":"pd","pd":"published 1909 in Chicago; public domain in the United States. The Project Gutenberg file also carries the Baha'i International Community notice","denom":[]},{"id":"abr-bahai-gathering","title":"For a Gathering","by":"'Abdu'l-Baha","year":1909,"trad":["bahai"],"type":"prayer","occasion":["celebration","peace","home"],"text":"O Lord of the Kingdom! Although we are assembled, yet we are Thy scattered ones; captives of Thy Shining Face. Although we are incapable, yet we anticipate the manifestation of Thy strength and ability. Although we are without capital and commodity, yet we are aided by the treasury of the Kingdom. Although we are a drop, yet we emanate from Thy sea of seas. Although we are an atom, yet we are illumined by Thy most bright Sun.\nO Lord! Confirm us so that each one in this gathering become a bright candle, a witness of the meeting, a caller to the Kingdom; that the world of matter become the mirror of heaven.","note":"A prayer to open a gathering: although we are a drop, yet we emanate from Thy sea.","voice":"brian","source":{"name":"Tablets of Abdul-Baha Abbas, vol. 1 (Bahai Publishing Society, Chicago, 1909), Project Gutenberg #19312","url":"https://www.gutenberg.org/ebooks/19312"},"rights":"pd","pd":"published 1909 in Chicago; public domain in the United States. The Project Gutenberg file also carries the Baha'i International Community notice","denom":[]},{"id":"abr-bahai-two-birds","title":"For Two Who Are Joined","by":"'Abdu'l-Baha","year":1909,"trad":["bahai"],"type":"prayer","occasion":["wedding","blessing"],"text":"O my God! O my God! I ask thee to protect these two birds in the orchard of Thy mercy, confirmed in joy and happiness in the garden of Thy bounties, warbling with the best melodies in the wood (garden) of Thy knowledge. Verily Thou art the Precious, the Mighty, the Protecting!","note":"A short blessing for a couple, like two birds in a garden of mercy.","voice":"jenny","source":{"name":"Tablets of Abdul-Baha Abbas, vol. 1 (Bahai Publishing Society, Chicago, 1909), Project Gutenberg #19312","url":"https://www.gutenberg.org/ebooks/19312"},"rights":"pd","pd":"published 1909 in Chicago; public domain in the United States. The Project Gutenberg file also carries the Baha'i International Community notice","denom":[]},{"id":"abr-bahai-departed-son","title":"On the Departure of a Son","by":"'Abdu'l-Baha","year":1909,"trad":["bahai"],"type":"reflection","occasion":["grief","funeral","comfort"],"text":"Be not sorrowful on account of the departure of thy good son. He hath indeed departed from this narrow and gloomy world which is darkened by unlimited sorrow, unto the Kingdom which is spacious, illumined, joyous and beautiful. God delivered him from this dark well and promoted him unto the Supreme Height! He gave him wings whereby he soared to the heaven of happiness. Verily this is the great mercy from Him who is precious and forgiving.","note":"Words of comfort sent to a mother whose son had died.","voice":"brian","source":{"name":"Tablets of Abdul-Baha Abbas, vol. 1 (Bahai Publishing Society, Chicago, 1909), Project Gutenberg #19312","url":"https://www.gutenberg.org/ebooks/19312"},"rights":"pd","pd":"published 1909 in Chicago; public domain in the United States. The Project Gutenberg file also carries the Baha'i International Community notice","denom":[]},{"id":"abr-bahai-babe-heaven","title":"For Parents Whose Baby Has Died","by":"'Abdu'l-Baha","year":1909,"trad":["bahai"],"type":"reflection","occasion":["grief","birth","comfort"],"text":"Truly, I say unto thee, thy child will be fostered from the breast of the gift of God in the Exalted Kingdom and will be nursed in the bosom of mercy in the Supreme World of God. Therefore, be filled with delight, for the favor of thy Lord is very great!","note":"Words of comfort for parents after the death of an infant.","voice":"jenny","source":{"name":"Tablets of Abdul-Baha Abbas, vol. 1 (Bahai Publishing Society, Chicago, 1909), Project Gutenberg #19312","url":"https://www.gutenberg.org/ebooks/19312"},"rights":"pd","pd":"published 1909 in Chicago; public domain in the United States. The Project Gutenberg file also carries the Baha'i International Community notice","denom":[]},{"id":"abr-gb-bahai-oneness","title":"One Human Family","by":"Grow With Grounded","year":2026,"trad":["bahai","all"],"type":"blessing","occasion":["peace","celebration"],"text":"May we see one another as leaves of one tree,\ndrops of one sea, flowers of one garden.\nMay our homes be places of welcome,\nour words be kind, and our work be service.\nMay this gathering add a little light to the world.","note":"A Grounded blessing in the spirit of the Baha'i teaching of the oneness of humanity.","voice":"brian","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded","denom":[]},{"id":"abr-sikh-mool-mantar","title":"The Mool Mantar","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"chant","occasion":["daily","morning","dying","funeral"],"text":"There is but one God whose name is true, the Creator, devoid of fear and enmity, immortal, unborn, self-existent by the favour of the Guru.","translit":"Ik Onkar, Sat Naam, Karta Purakh, Nirbhau, Nirvair, Akaal Moorat, Ajooni, Saibhang, Gur Prasad.","note":"The opening of the Guru Granth Sahib and of the Japji, recited each morning and at the end of life.","voice":"jenny","source":{"name":"M. A. Macauliffe, The Sikh Religion, vol. 1 (1909), sacred-texts.com","url":"https://sacred-texts.com/skh/tsr1/tsr121.htm"},"rights":"pd","pd":"published 1909 by Clarendon Press; Macauliffe died 1913","denom":[]},{"id":"abr-sikh-japji-1","title":"From the Japji: The Will of the Commander","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["daily","morning","peace"],"text":"By thinking I cannot obtain a conception of Him, even though I think hundreds of thousands of times.\nEven though I be silent and keep my attention firmly fixed on Him, I cannot preserve silence.\nThe hunger of the hungry for God subsideth not though they obtain the load of the worlds.\nIf man should have thousands and hundreds of thousands of devices, even one would not assist him in obtaining God.\nHow shall man become true before God? How shall the veil of falsehood be rent?\nBy walking, O Nanak, according to the will of the Commander as preordained.","translit":"Sochai soch na hova'ee, je sochee lakh vaar.","note":"The first stanza of the Japji, Guru Nanak's morning prayer.","voice":"brian","source":{"name":"M. A. Macauliffe, The Sikh Religion, vol. 1 (1909), sacred-texts.com","url":"https://sacred-texts.com/skh/tsr1/tsr121.htm"},"rights":"pd","pd":"published 1909 by Clarendon Press; Macauliffe died 1913","denom":[]},{"id":"abr-gb-sikh-ardas","title":"On the Closing Words of Ardas","by":"Grow With Grounded","year":2026,"trad":["sikh"],"type":"reflection","occasion":["daily","blessing","hope"],"text":"Every Ardas ends by asking for rising spirits through the Name,\nand for the good of all.\nThese words hold a whole way of living:\nhope that keeps climbing, and a heart wide enough for everyone.\nMay that spirit stay with this family today.","translit":"Nanak naam chardi kala, tere bhane sarbat da bhala.","note":"A Grounded reflection on the closing line of the Ardas, the Sikh community prayer; the Ardas itself is led by the family or the granthi.","voice":"jenny","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded","denom":[]},{"id":"abr-gb-sikh-sohila","title":"At the Close of the Day","by":"Grow With Grounded","year":2026,"trad":["sikh"],"type":"reflection","occasion":["evening","funeral","grief"],"text":"As the day closes, the hymns of Sohila are sung.\nThey are sung at bedtime, and they are sung at the end of a life.\nThe same words carry us into rest each night\nand carry our loved ones into the light of the Divine.\nMay this family rest in that light tonight.","translit":"Sohila.","note":"A Grounded word for the time of Kirtan Sohila, the bedtime prayer that is also recited at a Sikh cremation.","voice":"brian","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded","denom":[]},{"id":"abr-gb-sikh-anand-karaj","title":"For an Anand Karaj","by":"Grow With Grounded","year":2026,"trad":["sikh"],"type":"blessing","occasion":["wedding","celebration"],"text":"Four times you walk around the Guru,\nand four times you begin again together.\nMay your life be a walk of blissful union,\ntwo bodies with one light,\nand may your home be full of seva, song, and joy.","translit":"Anand Karaj.","note":"A Grounded blessing for guests at a Sikh wedding, held around the Guru Granth Sahib with the four Lavan.","voice":"jenny","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded","denom":[]},{"id":"abr-zor-ashem-vohu","title":"Ashem Vohu","by":"Avesta","tr":"James Darmesteter","year":1883,"trad":["zoroastrian"],"type":"chant","occasion":["daily","morning","dying","funeral"],"text":"Holiness is the best of all good.\nWell is it for it, well is it for that holiness which is perfection of holiness!","translit":"Ashem vohu vahishtem asti.","note":"One of the most often said Zoroastrian prayers, said through the day and at the bedside.","voice":"jenny","source":{"name":"The Zend-Avesta, part 2, tr. James Darmesteter (Sacred Books of the East, vol. 23, 1883), sacred-texts.com","url":"https://sacred-texts.com/zor/sbe23/sbe2306.htm"},"rights":"pd","pd":"published 1883; Darmesteter died 1894","denom":[]},{"id":"abr-zor-ahuna-vairya","title":"Yatha Ahu Vairyo","by":"Avesta","tr":"James Darmesteter","year":1880,"trad":["zoroastrian"],"type":"chant","occasion":["daily","blessing"],"text":"The will of the Lord is the law of righteousness.\nThe gifts of Vohu-mano to the deeds done in this world for Mazda.\nHe who relieves the poor makes Ahura king.","translit":"Yatha ahu vairyo atha ratush ashatchit hacha.","note":"The holiest Zoroastrian prayer, the Ahunavar, said at every turning of life.","voice":"brian","source":{"name":"Epiphanius Wilson (ed.), Sacred Books of the East (1900), the Zend-Avesta tr. James Darmesteter, Project Gutenberg","url":"https://www.gutenberg.org/ebooks/12894"},"rights":"pd","pd":"published 1880; Darmesteter died 1894","denom":[]},{"id":"abr-gb-zor-good-thoughts","title":"Good Thoughts, Good Words, Good Deeds","by":"Grow With Grounded","year":2026,"trad":["zoroastrian"],"type":"blessing","occasion":["daily","morning","funeral"],"text":"Good thoughts, good words, good deeds.\nMay our thoughts be clear as morning light.\nMay our words be true and kind.\nMay our deeds bring help to the poor and joy to the world.\nAnd may the good we do keep shining after us.","translit":"Humata, hukhta, hvarshta.","note":"A Grounded blessing built on the threefold path at the heart of Zoroastrian life.","voice":"jenny","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded","denom":[]},{"id":"abr-gb-zor-passing","title":"For a Zoroastrian Family in Mourning","by":"Grow With Grounded","year":2026,"trad":["zoroastrian"],"type":"blessing","occasion":["grief","funeral"],"text":"We honor a life of good thoughts, good words, and good deeds.\nMay the prayers of these days carry the soul across the bridge into light,\nand may this family be held in warmth and truth.\nThe good that was done lives on in all of us.","note":"A Grounded word for visitors in the days of prayers after a death; the family and priests lead the rites.","voice":"brian","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded","denom":[]},{"id":"abr-gb-zor-nowruz","title":"A Nowruz Blessing","by":"Grow With Grounded","year":2026,"trad":["zoroastrian","muslim","bahai"],"type":"blessing","occasion":["season","celebration","nature"],"text":"The days grow long and the earth turns green again.\nMay this new year bring health to every body,\nlight to every home, and peace between every neighbor.\nMay what is fresh in the fields grow fresh in our hearts.","note":"A Grounded blessing for the Persian New Year at the spring equinox, kept by many faiths.","voice":"jenny","source":{"name":"Grow With Grounded","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"written by Grow With Grounded","denom":[]}];
